const trig = $('When Called').first().json;
const impact = (trig.impact || '').toString().trim();
const REAL_TIERS = ['Niski','Średni','Wysoki','Krytycznie ważne'];
const idx = REAL_TIERS.indexOf(impact);
if (idx <= 0) {
  return [{ json: { floor: true, impact_in: impact } }];
}
const belowImpact = REAL_TIERS[idx - 1];
const rows = $input.all().map(function (i) { return i.json; });
const row = rows.find(function (r) { return r.impact === belowImpact; });
if (!row || !row.litellm_model) {
  return [{ json: { floor: true, impact_in: impact, missing_below: belowImpact } }];
}
return [{ json: {
  floor: false,
  impact: row.impact,
  litellm_model: row.litellm_model,
  max_tokens: (row.max_tokens != null) ? Number(row.max_tokens) : null,
  temperature: (row.temperature != null && row.temperature !== '') ? Number(row.temperature) : null
} }];
